/*
 * A116080  Permutation of natural numbers generated by 4-rowed array shown
 *          below.
 * https://oeis.org/A116080
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 250, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 * Formula: a(n) = 4*(k-i) + i, where n-1 = k + d with k and d determined by:
 *   - For n-1 < 1  -> k = 0
 *   - For n-1 < 3  -> k = 1
 *   - For n-1 < 6  -> k = 2
 *   - Else         -> k = 3 + (n-1-6)/4
 *   - d = (n-1) - (S(k-1)) with 
 *       S(k-1) = 0 (k=0), 1 (k=1), 3 (k=2), or 4*k-6 (k>=3)
 *   - i = d
 * This generates the OEIS sequence A116080, a permutation of natural numbers.
 */
seq_t a(idx_t n)
{
    idx_t n0 = n - 1;                 /* zero‑based index */
    idx_t k;

    if (n0 < 1) {
        k = 0;
    } else if (n0 < 3) {
        k = 1;
    } else if (n0 < 6) {
        k = 2;
    } else {
        k = 3 + (n0 - 6) / 4;        /* k >= 3 for n0 >= 6 */
    }

    idx_t prevSum;
    if (k == 0) {
        prevSum = 0;
    } else if (k == 1) {
        prevSum = 1;                 /* S(0) */
    } else if (k == 2) {
        prevSum = 3;                 /* S(1) */
    } else {
        prevSum = 4 * k - 6;         /* S(k-1) for k >= 3 */
    }

    idx_t d = n0 - prevSum;          /* offset within the diagonal (0 <= d <= 3) */
    seq_t i = (seq_t)d;              /* row index (0..3) */
    seq_t value = 4 * (seq_t)(k - d) + i;   /* a(n) = 4*(k-i) + i */
    return value;
}
